const batch = $input.first().json.body;
if (!Array.isArray(batch?.projects) || batch.projects.length === 0) {
  throw new Error('Expected a Vollna job notification with at least one project. Check the selected filters.');
}

function jobId(raw) {
  if (typeof raw !== 'string') throw new Error('Project has no posting URL.');
  let link = raw;
  if (/^https:\/\/(?:www\.)?vollna\.com\/go\?/i.test(raw)) {
    const target = raw.match(/[?&]url=([^&#]+)/i);
    if (!target) throw new Error('The tracked job link has no destination.');
    link = target[1];
    for (let pass = 0; pass < 3 && !/^https:\/\//i.test(link); pass++) link = decodeURIComponent(link);
  }
  const match = link.match(/^https:\/\/(?:www\.)?upwork\.com\/jobs\/(?:[^/?#]*_)?(?:~|%7e)([a-z0-9]+)\/?(?:[?#].*)?$/i);
  if (!match) throw new Error('Cannot identify an Upwork job. Keep the delivery for inspection.');
  return '~' + match[1];
}

function sorted(value) {
  if (Array.isArray(value)) return value.map(sorted);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.keys(value).sort().map(key => [key, sorted(value[key])]));
  }
  return value;
}

return batch.projects.map(project => {
  if (typeof project?.title !== 'string' || !project.title.trim()) throw new Error('A project has no title.');
  const id = jobId(project.url);
  const job = {...project, url: 'https://www.upwork.com/jobs/' + id};
  // A notification can report the same posting under a different set of filters.
  delete job.filters;
  const canonical = sorted(job);
  return {json: {jobId: id, job: canonical, revisionInput: JSON.stringify(canonical)}};
});
